"""Generate the static Hiirad company website. Run from any working directory."""
from pathlib import Path
from html import escape
from urllib.parse import quote
import json

ROOT = Path(__file__).resolve().parents[1]
NAV = [('index.html','Home'),('about.html','Who we are'),('divisions.html','Our divisions'),('projects.html','Projects'),('contact.html','Contact')]
DIVISIONS = [
 dict(slug='enterprise', title='Hiirad Enterprise', label='Wholesale & retail', image='city', headline='Your next opportunity.<br><em>Our connected network.</em>', intro='Connecting products, suppliers and business buyers through wholesale sourcing and digital retail.', body='Hiirad Enterprise Network brings together everyday shopping and business purchasing. Its online catalogue spans fashion, electronics, health and beauty, home and office, sports and outdoor essentials, and travel accessories.', items=[('Wholesale sourcing','Share your product links, specifications, quantities and delivery destination. Pricing, minimum order quantities and availability are confirmed by quotation.'),('Retail connections','Explore the current collections through Hiirad Enterprise, with products for individuals, families and businesses.'),('Reseller opportunities','Independent resellers can explore sourcing, business planning and practical learning through the Hiirad reseller programme.')], topic='Wholesale and retail', extra='<a class="text-link" href="https://hiirad.net/">Explore Hiirad Enterprise <span>↗</span></a><a class="text-link" href="https://hiirad.uk/pages/wholesale">View the wholesale catalogue <span>↗</span></a>'),
 dict(slug='logistics',title='Hiirad Logistics',label='Trade & logistics',image='city',headline='Connecting markets.<br><em>Moving possibilities.</em>',intro='Air, sea and road logistics for parcels, products and commercial cargo.',body='From a single parcel to a larger consignment, a useful shipping conversation starts with the details. Hiirad helps individuals and businesses explore international transport options according to the route, shipment and service available.',items=[('Air freight','Discuss time-sensitive shipments, international air cargo and available express options.'),('Sea freight','Explore options for larger consignments and bulk goods, based on your origin, destination and cargo.'),('Road transport','Enquire about regional and cross-border movement of parcels, pallets and business shipments.')],topic='Trade and logistics',extra='<a class="text-link" href="https://hiirad.uk/pages/logistics">Visit the Hiirad logistics portal <span>↗</span></a>'),
 dict(slug='digital-commerce',title='Digital Commerce',label='Technology',image='office',headline='Commerce, connected.<br><em>Possibility, amplified.</em>',intro='Digital retail experiences and business tools that bring products and people together.',body='Hiirad’s digital commerce focus connects online product discovery with practical business relationships. The Enterprise storefront and reseller programme provide starting points for buyers, suppliers and independent sellers.',items=[('Product discovery','Connect customers with clear product information and relevant collections.'),('Reseller connections','Explore the Hiirad reseller programme for sourcing guidance, learning and account access.'),('Business development','Introduce a digital commerce idea, a product range or a collaboration you would like to discuss.')],topic='Digital commerce',extra='<a class="text-link" href="https://hiirad.uk/pages/reseller">Explore the reseller programme <span>↗</span></a>'),
 dict(slug='fishing',title='Hiirad Fishing',label='Marine enterprise',image='city',headline='A shared opportunity.<br><em>Beyond the shoreline.</em>',intro='Exploring fishing and seafood ventures through producer, buyer and commercial partnerships.',body='Our marine enterprise focus welcomes conversations about seafood supply, market requirements and partnership opportunities. Each enquiry starts with an understanding of the product, its origin and the needs of the buyer.',items=[('Producer enquiries','Introduce your products, origin, available quantities and relevant documentation.'),('Buyer requirements','Share the species, product format, packaging, destination and quantities you need.'),('Commercial partnerships','Discuss a potential venture and the expertise, resources and relationships it would require.')],topic='Fishing and seafood',extra=''),
 dict(slug='resources',title='Resources',label='Natural resources',image='city',headline='Considered development.<br><em>Long-term perspective.</em>',intro='Exploring natural-resource opportunities through clear, responsible commercial relationships.',body='Hiirad’s resource interests include potential mining and refinery partnerships. We approach each introduction as a conversation about its commercial context, requirements and suitability.',items=[('Opportunity assessment','Introduce the location, development stage and scope of your proposal.'),('Partnership conversations','Explain the technical expertise, investment or commercial relationship being sought.'),('A considered approach','Clear documentation and an understanding of responsibilities help establish the basis for further discussion.')],topic='Resources',extra=''),
 dict(slug='partnerships',title='Franchises & Partnerships',label='Business partnerships',image='office',headline='Build with purpose.<br><em>Grow together.</em>',intro='Bringing local understanding and shared ambition to new business opportunities.',body='We welcome introductions from suppliers, independent resellers and prospective business partners. Our franchise and partnership interests centre on commercial fit, practical planning and relationships that can develop over time.',items=[('Suppliers','Tell us about your product range, capacity, location and the markets you serve.'),('Independent resellers','Explore sourcing and learning through the Hiirad Enterprise reseller programme.'),('Franchise & venture ideas','Introduce your business concept, target market and proposed collaboration.')],topic='Franchises',extra='<a class="text-link" href="https://hiirad.uk/pages/reseller">Discover the reseller programme <span>↗</span></a>')
]

def btn(text, href='contact.html', secondary=False):
 return f'<a class="button{" secondary" if secondary else ""}" href="{escape(href,quote=True)}">{text} <span aria-hidden="true">↗</span></a>'

def header(active):
 links=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==active else '')+f'>{t}</a>' for p,t in NAV)
 return f'''<a class="skip" href="#main">Skip to content</a>
 <div class="contact-strip"><div class="wrap"><span>London roots. Global outlook.</span><div><a href="tel:+447447794712">+44 7447 794712</a><a href="mailto:info@hiirad.net">info@hiirad.net</a></div></div></div>
 <header class="site-header"><nav class="wrap" aria-label="Main navigation"><a class="brand" href="index.html" aria-label="Hiirad home"><img src="assets/hiirad-logo.webp" width="1254" height="1254" alt="Hiirad"></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation" aria-label="Open navigation">Menu <span aria-hidden="true">☰</span></button><div class="nav-links" id="navigation">{links}</div><a class="header-cta" href="contact.html">Request a quote <span aria-hidden="true">↗</span></a></nav></header>'''

def footer():
 return '''<footer><div class="wrap footer-grid"><div><a class="footer-brand" href="index.html"><img src="assets/hiirad-logo.webp" width="1254" height="1254" alt="Hiirad home"></a><p>Enterprise without borders.<br>Connecting commerce, people<br>and possibility.</p></div><div><h2>Discover Hiirad</h2><a href="about.html">Who we are</a><a href="divisions.html">Our divisions</a><a href="projects.html">Projects & initiatives</a><a href="contact.html">Request a quote</a></div><div><h2>Our network</h2><a href="enterprise.html">Hiirad Enterprise</a><a href="logistics.html">Hiirad Logistics</a><a href="partnerships.html">Partnerships</a><a href="https://hiirad.net/">Enterprise website ↗</a></div><div><h2>Let’s talk</h2><a href="mailto:info@hiirad.net">info@hiirad.net</a><a href="tel:+447447794712">+44 7447 794712</a><p>London, United Kingdom</p><a href="contact.html">Start a conversation ↗</a></div></div><div class="wrap footer-bottom"><span>© <span data-year>2026</span> Hiirad Ltd. All rights reserved.</span><a href="privacy.html">Website privacy</a><a href="#top">Back to top ↑</a></div></footer>'''

def cta():
 return '<section class="cta"><div class="wrap"><div><p class="eyebrow">Let’s make the next connection</p><h2>Your ambition.<br><em>Our next conversation.</em></h2></div>'+btn('Request a quote')+'</div></section>'

def page(file,title,desc,body,active=None):
 schema={'@context':'https://schema.org','@type':'Organization','name':'Hiirad Ltd','url':'https://hiirad.com/','logo':'https://hiirad.com/assets/hiirad-logo.webp','email':'info@hiirad.net','telephone':'+447447794712'}
 (ROOT/file).write_text(f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Hiirad</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="theme-color" content="#064b36"><link rel="canonical" href="https://hiirad.com/{'' if file=='index.html' else file}"><meta property="og:title" content="{escape(title,quote=True)} | Hiirad"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:image" content="https://hiirad.com/assets/hiirad-logo.webp"><link rel="icon" href="assets/hiirad-logo.webp" type="image/webp"><link rel="stylesheet" href="assets/style.css"><script src="assets/site.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body id="top">{header(active or file)}<main id="main">{body}</main>{footer()}</body></html>''')

def intro(label,title,text,image='city'):
 return f'<section class="page-hero"><img src="assets/{image}.jpg" alt="" width="1800" height="1200"><div class="wrap"><p class="eyebrow">{label}</p><h1>{title}</h1><p class="hero-description">{text}</p></div></section>'

def division_cards():
 return '<div class="division-grid">'+''.join(f'<a class="division-card" id="division-{i:02}" href="{d["slug"]}.html"><div class="card-top"><span>{i:02} / {d["label"]}</span><span aria-hidden="true">↗</span></div><h3>{d["title"]}</h3><p>{d["intro"]}</p><span class="card-link">Explore this division</span></a>' for i,d in enumerate(DIVISIONS,1))+'</div>'

slides=[('city','A world of opportunity','Enterprise<br><em>without borders.</em>','Connecting commerce, people and possibilities across the UK, Africa and global markets.','Explore our divisions','divisions.html'),('city','Hiirad Enterprise & Logistics','From your ambition<br><em>to new markets.</em>','Discover wholesale sourcing and logistics options built around your business requirements.','Discover Hiirad Enterprise','enterprise.html'),('office','Built on relationships','Better connections.<br><em>Shared possibilities.</em>','Introduce your business, explore a partnership and take the next step with Hiirad.','Explore partnerships','partnerships.html')]
hero='<section class="hero-carousel" aria-roledescription="carousel" aria-label="Discover Hiirad">'
for i,(img,label,title,text,link,url) in enumerate(slides):
 tag='h1' if i==0 else 'h2'
 hero+=f'<article class="hero-slide" data-slide="{i}" role="group" aria-roledescription="slide" aria-label="{i+1} of 3"'+(' hidden' if i else '')+f'><img class="hero-image" src="assets/{img}.jpg" width="1800" height="1200" alt="" '+('fetchpriority="high"' if i==0 else 'loading="lazy"')+f'><div class="wrap hero-content"><p class="eyebrow">{label}</p><{tag}>{title}</{tag}><p class="hero-description">{text}</p><div class="actions">{btn("Request a quote")}{btn(link,url,True)}</div></div></article>'
hero+='''<div class="carousel-controls wrap" hidden><div class="carousel-dots" aria-label="Choose slide"><button aria-label="Show slide 1" aria-pressed="true" data-go="0">01</button><button aria-label="Show slide 2" aria-pressed="false" data-go="1">02</button><button aria-label="Show slide 3" aria-pressed="false" data-go="2">03</button></div><div class="carousel-arrows"><button data-prev aria-label="Previous slide">←</button><button data-next aria-label="Next slide">→</button><button class="pause" data-pause aria-label="Pause slideshow">Pause</button></div></div><span class="sr-only" id="slide-status" aria-live="polite"></span></section>'''
home=hero+'''<section class="promise-band"><div class="wrap"><div><span>01</span><div><h2>Commercial understanding</h2><p>A clear starting point for your business needs.</p></div></div><div><span>02</span><div><h2>International outlook</h2><p>Connecting local ambition with wider markets.</p></div></div><div><span>03</span><div><h2>Shared opportunity</h2><p>Relationships built through useful conversations.</p></div></div></div></section>
<section class="section wrap split"><div class="photo-frame"><img src="assets/office.jpg" width="1800" height="1200" loading="lazy" alt="A bright contemporary workspace"><span>London roots. Global outlook.</span></div><div><p class="eyebrow">Welcome to Hiirad</p><h2>One vision.<br><em>A world of possibility.</em></h2><p class="lead">We bring people, products and commercial ideas together.</p><p>Hiirad is a UK-based enterprise with interests in commerce, logistics, technology and international business development. We connect practical needs with the relationships and opportunities that can move them forward.</p><p>From sourcing products to exploring a new venture, every conversation starts with understanding what matters to your business.</p>'''+btn('Get to know Hiirad','about.html')+'''</div></section>
<section class="section muted"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Our divisions</p><h2>Different industries.<br><em>Shared ambition.</em></h2></div><p>Explore our business interests and find the right place to start your conversation.</p></div>'''+division_cards()+'''</div></section>
<section class="enterprise-feature"><img src="assets/city.jpg" alt="" width="1800" height="1200" loading="lazy"><div class="wrap"><p class="eyebrow">Hiirad Enterprise Network</p><h2>From product discovery<br>to <em>business opportunity.</em></h2><p>Explore consumer collections, discuss bulk purchasing and connect with the Hiirad reseller programme.</p><div class="actions">'''+btn('Explore Enterprise','enterprise.html')+btn('Discuss your requirements','contact.html?topic=Wholesale%20and%20retail',True)+'''</div></div></section>
<section class="section wrap"><div class="section-heading"><div><p class="eyebrow">A clear next step</p><h2>Good business starts<br><em>with a conversation.</em></h2></div><p>Share the essentials. We can then discuss availability, suitability and the next steps for your enquiry.</p></div><div class="steps"><article><span>01</span><h3>Tell us what you need</h3><p>Choose a division and describe your products, shipment or proposed partnership.</p></article><article><span>02</span><h3>Add the useful details</h3><p>Include quantities, locations and your preferred timescale so the conversation has a clear starting point.</p></article><article><span>03</span><h3>Discuss your options</h3><p>Contact the team to confirm scope, pricing and availability before making a commitment.</p></article></div></section>'''+cta()
page('index.html','Enterprise without borders','Hiirad connects commerce, logistics, technology and international partnerships. Explore our divisions and request a quote.',home)

about=intro('Who we are','Ambition grounded<br><em>in purpose.</em>','A UK-based enterprise connecting commercial ideas, people and possibilities.')+'''<section class="section wrap split"><div><p class="eyebrow">The Hiirad approach</p><h2>Built on relationships.<br><em>Focused on possibility.</em></h2><p class="lead">Useful connections are at the heart of our business.</p><p>Hiirad Ltd brings together commerce, logistics, technology and international business development, with London as our base. Our divisions share a practical approach: understand the need, explore the opportunity and establish a clear way forward.</p><p>Hiirad Enterprise Network connects retail collections with wholesale enquiries and reseller opportunities. Alongside this, our wider business interests include marine enterprise, natural resources and partnership development.</p><p>We welcome conversations with buyers, suppliers and business partners who share an interest in building lasting commercial value.</p></div><div class="photo-frame"><img src="assets/city.jpg" alt="Contemporary business architecture" width="1800" height="1200" loading="lazy"><span>Local understanding. International perspective.</span></div></section><section class="section muted"><div class="wrap"><p class="eyebrow">What guides us</p><h2>Our principles.<br><em>In practice.</em></h2><div class="principles">'''
for num,title,text in [('01','Trust first','Clear communication and dependable relationships form the foundation of our work.'),('02','A global perspective','We bring local understanding to conversations across international markets.'),('03','Practical innovation','We explore technology and new business models where they can make a useful difference.'),('04','Shared opportunity','We aim to create commercial value with customers, suppliers and partners.')]:
 about+=f'<article><span>{num}</span><h3>{title}</h3><p>{text}</p></article>'
about+='</div></div></section>'+cta()
page('about.html','Who we are','Meet Hiirad, a UK-based enterprise focused on commerce, logistics, digital opportunities and international business relationships.',about)

page('divisions.html','Our divisions','Explore Hiirad Enterprise, Logistics, Digital Commerce, Fishing, Resources and Partnerships.',intro('Our divisions','One connected vision.<br><em>Many possibilities.</em>','Discover our commercial activities and areas of development. Each division has its own focus and a dedicated point of enquiry.')+'<section class="section wrap">'+division_cards()+'</section>'+cta())

for d in DIVISIONS:
 content=intro(d['label'],d['headline'],d['intro'],d['image'])+f'<section class="section wrap split"><div><p class="eyebrow">{d["title"]}</p><h2>A clear focus.<br><em>A useful connection.</em></h2></div><div><p class="lead">{d["body"]}</p><div class="stack-links">{d["extra"]}</div></div></section><section class="muted section"><div class="wrap"><div class="steps">'
 for i,(title,text) in enumerate(d['items'],1): content+=f'<article><span>0{i}</span><h3>{title}</h3><p>{text}</p></article>'
 content+=f'</div></div></section><section class="section wrap split"><div><p class="eyebrow">Start a conversation</p><h2>Let’s understand<br><em>your requirements.</em></h2></div><div><p>Tell us about your business, the opportunity and the outcome you have in mind. Include your location, relevant quantities or specifications, and preferred timescale.</p><p>Scope, availability and commercial terms are discussed for each enquiry.</p>{btn("Enquire about this division","contact.html?topic="+quote(d["topic"]))}</div></section><div class="wrap back-link"><a class="text-link" href="divisions.html">← All divisions</a></div>'
 page(d['slug']+'.html',d['title'],d['intro'],content,'divisions.html')

projects=intro('Projects & initiatives','Ideas with<br><em>a way forward.</em>','Our focus areas connect digital commerce, sourcing relationships and new commercial opportunities.','office')+'<section class="section wrap project-list">'
for i,(tag,title,text,url,image) in enumerate([('Digital retail','Hiirad Enterprise Network','An online destination for consumer collections, with routes into wholesale purchasing and the Hiirad reseller programme.','enterprise.html','office'),('Business buying','Wholesale sourcing','A dedicated quotation route for business buyers to discuss product requirements, quantities and delivery destinations.','https://hiirad.uk/pages/wholesale','city'),('International trade','Logistics connections','Air, sea and road enquiries that begin with shipment details, route requirements and available transport options.','logistics.html','city'),('Business development','Partnerships & new ventures','Exploring commercial ideas with suppliers, resellers and prospective business partners.','partnerships.html','city')],1):
 projects+=f'<article class="project-row"><img src="assets/{image}.jpg" alt="" width="1800" height="1200" loading="lazy"><div><p class="eyebrow">0{i} / {tag}</p><h2>{title}</h2><p>{text}</p>{btn("Explore this initiative",url)}</div></article>'
projects+='</section>'+cta()
page('projects.html','Projects & initiatives','Explore Hiirad’s digital retail, wholesale sourcing, logistics and business partnership initiatives.',projects)

topics=['General enquiry']+[d['topic'] for d in DIVISIONS]+['Supplier networks','International trade','New ventures']
options=''.join(f'<option>{t}</option>' for t in topics)
contact=intro('Contact & quotations','Let’s build<br><em>your next opportunity.</em>','Tell us what you need. Start a quote enquiry or introduce a partnership.','office')+f'''<section class="section wrap contact-layout"><aside><p class="eyebrow">Start a conversation</p><h2>Good connections<br><em>start here.</em></h2><p>Speak to Hiirad about products, shipping or a business opportunity.</p><div class="contact-method"><span>Email</span><a href="mailto:info@hiirad.net">info@hiirad.net ↗</a></div><div class="contact-method"><span>Telephone</span><a href="tel:+447447794712">+44 7447 794712 ↗</a></div><div class="contact-method"><span>Our base</span><strong>London, United Kingdom</strong></div><div class="contact-note"><h3>Prefer an online message?</h3><p>Use the contact form on our Enterprise website to send your enquiry online.</p><a class="text-link" href="https://hiirad.uk/pages/contact">Open online contact form ↗</a></div></aside><div class="quote-panel"><p class="eyebrow">Your requirements</p><h2>Request a quote</h2><p>Prepare your enquiry below, then send it using your email app. You can review the message first.</p><form id="enquiry-form"><div class="form-grid"><label>Your name <span>*</span><input name="name" autocomplete="name" required maxlength="100"></label><label>Email address <span>*</span><input type="email" name="email" autocomplete="email" required maxlength="150"></label><label>Company <small>(optional)</small><input name="company" autocomplete="organization" maxlength="120"></label><label>Phone <small>(optional)</small><input type="tel" name="phone" autocomplete="tel" maxlength="40"></label><label class="full">Enquiry topic <span>*</span><select name="topic" id="topic" required>{options}</select></label><label>Country / destination <span>*</span><input name="country" autocomplete="country-name" required maxlength="100"></label><label>Preferred timescale <small>(optional)</small><input name="timescale" placeholder="e.g. Within the next month" maxlength="100"></label><label class="full">What do you need? <span>*</span><textarea name="message" id="message" rows="6" required maxlength="1500" aria-describedby="message-hint" placeholder="Tell us about the products, quantities, shipment or partnership you have in mind."></textarea></label></div><p id="message-hint" class="form-hint">For a product quote, include specifications and quantities. For shipping, include origin, destination, weight and dimensions.</p><p class="form-hint">These details stay in your browser until you choose to send them. <a href="privacy.html">Website privacy</a>.</p><button type="submit" class="button">Review my enquiry <span aria-hidden="true">↗</span></button><noscript><p>To request a quote, email <a href="mailto:info@hiirad.net">info@hiirad.net</a> or use the online contact form linked on this page.</p></noscript></form><section id="quote-review" hidden aria-labelledby="review-title" tabindex="-1"><h3 id="review-title">Your enquiry is ready to review</h3><pre id="quote-text"></pre><div class="actions"><a id="send-email" class="button" href="mailto:info@hiirad.net">Open email draft ↗</a><button type="button" id="copy-quote" class="button outline">Copy enquiry</button></div><p class="form-hint">Opening a draft does not send it. Review and send it in your email app. If an email app is unavailable, copy your enquiry into the <a href="https://hiirad.uk/pages/contact">online contact form</a>.</p></section><p id="form-status" role="status" aria-live="polite"></p></div></section><section class="section muted"><div class="wrap faq"><p class="eyebrow">Before you get in touch</p><h2>A few useful answers.</h2><details><summary>What should I include in a wholesale quote request?</summary><p>Include product links or specifications, quantities, your business name, delivery country and preferred timescale. Prices, minimum order quantities and availability are confirmed by quotation.</p></details><details><summary>Can I enquire about international shipping?</summary><p>Yes. Include collection and destination locations, parcel count, dimensions and total weight. Hiirad can discuss the available air, sea or road options for your shipment.</p></details><details><summary>How do I introduce a partnership?</summary><p>Choose the relevant division and describe your company, proposed collaboration, target market and the support or relationship you are seeking.</p></details><details><summary>Does this form send my enquiry automatically?</summary><p>No. It prepares a message for you to review and send through your email app. You can also use the online contact form on the Hiirad Enterprise website.</p></details></div></section>'''
page('contact.html','Request a quote','Contact Hiirad for wholesale, logistics and partnership enquiries. Prepare your quote requirements or contact the team directly.',contact)

privacy=intro('Website privacy','Clear information.<br><em>In your hands.</em>','How this company website handles your enquiry details.')+'''<section class="section wrap prose"><h2>Quote enquiry form</h2><p>The form on this website prepares a message in your browser. It does not submit your form entries to a website database or save them in browser storage. Clicking “Open email draft” passes the enquiry into your email application. You decide whether to send it.</p><h2>Copying your enquiry</h2><p>The “Copy enquiry” button copies your prepared message to your device clipboard. You can then paste it into an email or the linked Enterprise contact form.</p><h2>Email and other websites</h2><p>If you send an email, your email provider and the recipient process that message. The Hiirad Enterprise website has its own contact form and privacy information. Follow its privacy links before using those services.</p><h2>Website delivery</h2><p>This static website is hosted through GitHub Pages. The website code does not set analytics or advertising cookies. The hosting provider may process connection information to deliver and secure the website. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a> for its practices.</p><h2>Questions</h2><p>For questions about information you share with Hiirad, contact <a href="mailto:info@hiirad.net">info@hiirad.net</a>.</p></section>'''
page('privacy.html','Website privacy','How the Hiirad company website handles quote enquiries, email drafts and external links.',privacy)

page('404.html','Page not found','Find your way back to Hiirad.',intro('Page not found','A different route<br><em>to opportunity.</em>','The page you requested could not be found.')+'<section class="section wrap">'+btn('Back to home','index.html')+'</section>')
files=['index.html','about.html','divisions.html','projects.html','contact.html','privacy.html']+[d['slug']+'.html' for d in DIVISIONS]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://hiirad.com/'+('' if f=='index.html' else f)+'</loc></url>' for f in files)+'</urlset>\n')
error_page = ROOT / '404.html'
error_page.write_text(error_page.read_text().replace('<head>', '<head><base href="/">', 1))
print(f'Generated {len(files)+1} pages and sitemap.')
